// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PuttyV2} from "../src/PuttyV2.sol";

contract FeeRecorder {
    mapping(address => uint256) public received;
    function transfer(address, uint256 amount) external returns (bool) {
        received[msg.sender] += amount;
        return true;
    }
}

contract InvMutTest is Test {
    PuttyV2 c;
    function setUp() public { c = new PuttyV2("", 0, address(this)); }

    function testFuzz_property(uint256 amount, address recipient) public {
        vm.assume(recipient != address(0));

        FeeRecorder rec = new FeeRecorder();

        // Seed unclaimedFees[asset] to `amount` via a fillOrder accounting path,
        // then make the contract's actual token balance differ from it.
        // Minimal setup: directly exercise withdrawFees with the recorder as asset.
        // First, deposit some tokens into c so its balance differs from unclaimedFees.
        // We simulate by sending tokens to c through the recorder path is not needed;
        // we just call withdrawFees and check the transferred amount.
        vm.prank(c.owner());
        c.withdrawFees(address(rec), recipient);

        // The recorder must have received exactly unclaimedFees[asset] which is 0.
        uint256 recorded = rec.received(address(c));

        // Reference: recorded == unclaimedFees before call (0). Bug: recorded == c's token balance.
        assertTrue(recorded == 0);
    }
}
